SourceCode.Declaration:
/// <summary>
/// The fleet of handhelds that have ever signed into ForeFront Mobile, one row per device.
///
/// Registered automatically - see registerSignIn - rather than through any setup screen. The
/// standard D365FO Warehouse app populates an equivalent list the same way: every sign-in tells
/// the AOS which physical device is asking, so IT gets a fleet inventory for free instead of
/// needing someone to maintain one by hand. Before this table existed, a device's identity only
/// ever showed up as an opaque DeviceId string on individual postings (HSMobileOpsPostQueue,
/// HSMobileOpsPostLog) - traceable after the fact, but with no answer to "what handhelds are
/// actually deployed at WMS-WHS right now" anywhere in D365FO.
///
/// DeviceId is generated client-side (see WorkerContextRepositoryImpl.deviceId) and is stable for
/// the life of an install, not a hardware serial - a factory reset or reinstall registers what
/// looks like a new device, which is the correct behaviour for a fleet MDM that should not need
/// privileged access to read real hardware identifiers.
///
/// `SaveDataPerCompany = No` - one fleet for the whole environment, not one per legal entity. A
/// physical handheld was never a per-company concept the way an order or an item is; the table
/// defaulted to per-company scoping anyway (the ordinary AX default for any table that doesn't
/// say otherwise) until this was confirmed live as a real bug, not just a theoretical one: a
/// device that had already signed in successfully under one company came back HTTP 500 -
/// DuplicateKeyException - the moment it signed in under a second one, because
/// registerSignIn's own lookup couldn't see the row it had already created elsewhere, concluded
/// "new device", and collided with an index that is unique regardless of company. Flipping this
/// on an already-populated table needed its existing rows cleared first (done by hand before the
/// build that carries this change) rather than a data-upgrade script - there was nothing worth
/// preserving row-by-row in a fleet-bookkeeping table that regenerates itself on every sign-in
/// anyway.
///
/// **A second, unrelated DuplicateKeyException, confirmed live afterward: LastWarehouseIdx
/// (below) needs AllowDuplicates=Yes stated explicitly.** Left unstated, it built as a unique
/// index on LastWarehouseId alone - meaning only one device in the whole fleet could ever be
/// recorded against any given warehouse, which is never true (a warehouse normally has several
/// handhelds working it at once). Every device after the first to share a warehouse collided on
/// this index during registerSignIn's insert, not DeviceIdIdx - producing the exact same
/// DuplicateKeyException/HTTP 500 shape as the bug above, including for a DeviceId that had never
/// been inserted anywhere. The two bugs looked identical from the app/API side (same exception
/// type, same generic "record already exists" message, which names the record's title fields -
/// FriendlyName/DeviceId - regardless of which index was actually violated) but had nothing to do
/// with each other.
/// </summary>
public class HSMobileOpsDevice extends common
{
}

Method.Source:
/// <summary>
/// Upserts this device's row from a successful sign-in.
///
/// Called from HSMobileOpsUserService::signIn once authentication has already succeeded -
/// never on its own, and never on a failed attempt, so this table only ever reflects devices
/// a real worker actually got into, not every handheld that tried a wrong password. Brand and
/// model are trusted as sent - a device lying about its own hardware is not a security
/// question this table answers - and are only ever overwritten with a non-blank value, so a
/// client that cannot read them (or an older app build that does not send them yet) does not
/// blank out what a previous sign-in already recorded.
///
/// </summary>
public static void registerSignIn(
    str                   _deviceId,
    str                   _deviceBrand,
    str                   _deviceModel,
    str                   _platform,
    str                   _platformVersion,
    str                   _appVersionName,
    HSMobileOpsUserName   _userName,
    InventSiteId          _siteId,
    InventLocationId      _warehouseId)
{
    HSMobileOpsDevice device;

    if (!_deviceId)
    {
        return;
    }

    ttsbegin;

    select forUpdate device
        where device.DeviceId == _deviceId;

    if (!device.RecId)
    {
        device.DeviceId     = _deviceId;
        device.IsActive     = NoYes::Yes;
        device.FirstSeenUtc = DateTimeUtil::utcNow();
    }

    if (_deviceBrand)
    {
        device.DeviceBrand = _deviceBrand;
    }
    if (_deviceModel)
    {
        device.DeviceModel = _deviceModel;
    }
    // Recomputed every sign-in rather than stored once, so a device that only had a model
    // the first time (an app build that added brand reporting later, say) picks up the
    // fuller name on its very next sign-in instead of being stuck with the old one.
    device.FriendlyName = HSMobileOpsDevice::friendlyName(device.DeviceBrand, device.DeviceModel);

    if (_platform)
    {
        device.Platform = _platform;
    }
    if (_platformVersion)
    {
        device.PlatformVersion = _platformVersion;
    }
    if (_appVersionName)
    {
        device.AppVersionName = _appVersionName;
    }

    device.LastUserName    = _userName;
    device.LastSiteId      = _siteId;
    device.LastWarehouseId = _warehouseId;
    device.LastSignInUtc   = DateTimeUtil::utcNow();

    if (device.RecId)
    {
        device.update();
    }
    else
    {
        device.insert();
    }

    ttscommit;
}

/// <summary>
/// "Zebra TC27", falling back to whichever of brand/model is actually known.
/// </summary>
private static str friendlyName(str _brand, str _model)
{
    if (_brand && _model)
    {
        return strFmt('%1 %2', _brand, _model);
    }

    return _brand ? _brand : _model;
}

/// <summary>
/// Whether this device has ever signed in before - see HSMobileOpsLicense and the signIn hook
/// in HSMobileOpsUserService. A known device always passes the license's device-count check,
/// no matter how full the fleet is; only a device D365FO has never seen before can be turned
/// away for that.
///
/// `final`, `[Wrappable(false)]` and `internal` for the same reason HSMobileOpsLicense::verify()
/// and HSMobileOpsUserService::signIn() are - a Chain of Command extension that always answered
/// true here would let any never-before-seen device silently skip the license's device-count
/// gate; only HSMobileOpsUserService (same package) needs to call this at all.
/// </summary>
[Wrappable(false), Hookable(false)]
internal static final boolean isKnownDevice(str _deviceId)
{
    HSMobileOpsDevice device;

    if (!_deviceId)
    {
        return false;
    }

    select firstOnly RecId from device
        where device.DeviceId == _deviceId;

    return device.RecId != 0;
}

/// <summary>
/// How many devices currently count against the license's device limit - see
/// HSMobileOpsLicense and the signIn hook in HSMobileOpsUserService. One row per device now
/// that this table is environment-wide (see the class doc's SaveDataPerCompany note), so a
/// plain row count is exactly right - no more risk of the same physical handheld being
/// counted once per company it has signed into.
///
/// `final`, `[Wrappable(false)]` and `internal` - see the same note on isKnownDevice.
/// </summary>
[Wrappable(false), Hookable(false)]
internal static final int activeDeviceCount()
{
    HSMobileOpsDevice device;
    int                deviceCount;

    while select device
        where device.IsActive == NoYes::Yes
    {
        deviceCount++;
    }

    return deviceCount;
}

/// <summary>
/// True when _deviceId may proceed under _maxDevices - either it is already known (see
/// isKnownDevice's own note: a known device always passes, regardless of fleet fullness), or
/// the fleet has room for one more. False means DEVICE_LIMIT_REACHED.
///
/// The one gate both HSMobileOpsUserService::signIn's own inline check and
/// HSMobileOpsLicenseService::registerDevice call, so the two can never drift apart -
/// signIn's check predates this method and is kept as a defense-in-depth safety net beneath
/// the app's own pre-flight license/registerDevice calls (see HSMobileOpsLicense's class
/// doc), not removed now that a second call site exists.
///
/// `final`, `[Wrappable(false)]` and `internal` for the same reason isKnownDevice/
/// activeDeviceCount are.
/// </summary>
[Wrappable(false), Hookable(false)]
internal static final boolean checkDeviceLimit(str _deviceId, int _maxDevices)
{
    if (!_deviceId)
    {
        return true;
    }

    if (HSMobileOpsDevice::isKnownDevice(_deviceId))
    {
        return true;
    }

    return HSMobileOpsDevice::activeDeviceCount() < _maxDevices;
}
